using System;
using UnityEngine;
using HarborValeGreybox.Workshop;
namespace HarborValeGreybox.Racing {
public sealed partial class RaceProgressStore {
 static WorkshopBuild ActiveWorkshopOf(RaceProgress p)=>p.fleet.selectedId==p.prototypeCarId?p.workshop:FleetLedger.Active(p.fleet);
 public string ActiveModelId=>Profile.fleet.selectedId==FleetLedger.Loaner?"car_finch":VehicleLineup.Model(FleetLedger.Find(Profile.fleet,Profile.fleet.selectedId));
 public WorkshopBuild ActiveWorkshop=>ActiveWorkshopOf(Profile);
 public string ActiveVehicleName=>Profile.fleet.selectedId==FleetLedger.Loaner?"RECOVERY LOANER / FINCH":FleetLedger.Find(Profile.fleet,Profile.fleet.selectedId).name;
 public bool CanUpgrade=>!Profile.fleet.HasPending&&Profile.fleet.selectedId!=FleetLedger.Loaner&&HasEngine(Profile.fleet.selectedId);
 TuneReceipt FleetTransaction(TuneReceipt receipt){using(Lock()){var latest=Load();foreach(var r in latest.spending)if(r.transactionId==receipt.transactionId){if(r.kind!=receipt.kind||r.partId!=receipt.partId||r.configId!=receipt.configId||(r.fleetJson??"")!=(receipt.fleetJson??"")||r.credits!=receipt.credits)throw new InvalidOperationException("Fleet request conflicts with committed transaction");Profile=latest;return r;}if(receipt.credits>latest.availableCredits)throw new InvalidOperationException("Not enough credits");var candidate=JsonUtility.FromJson<RaceProgress>(JsonUtility.ToJson(latest));receipt.prototypeCarId=candidate.prototypeCarId;candidate.spending.Add(receipt);candidate.availableCredits=checked(candidate.availableCredits-receipt.credits);Validate(candidate,true);Write(candidate);Profile=candidate;return receipt;}}
 TuneReceipt Receipt(string request,string kind,string part,string config="",int credits=0,string json=null){if(!Guid.TryParse(request,out _))throw new ArgumentException("Invalid transaction identity");return new TuneReceipt{transactionId=request,kind=kind,partId=part,configId=config,pathId="fleet_v7",stage=0,credits=credits,paidUtc=DateTime.UtcNow.ToString("o"),fleetJson=json};}
 public void SelectVehicle(string request,string id)=>FleetTransaction(Receipt(request,"fleet_select",id));
 public void BuyVehicle(string request,string model,int quote){var spec=VehicleLineup.Find(model);if(quote!=spec.price)throw new InvalidOperationException("Car quote changed");var r=Receipt(request,"fleet_car",Profile.profileId+":vehicle:"+request,model,quote);r.pathId="fleet_v8";FleetTransaction(r);}
 public void BuyReplacement(string request)=>FleetTransaction(Receipt(request,"fleet_buy",Profile.profileId+":replacement:"+request,credits:RivalsData.Load().replacementPrice));
 public DuelContract BeginDuel(string request,string opponent,string mode){Refresh();if(!HasEngine(Profile.fleet.selectedId))throw new InvalidOperationException("Install an engine before racing this car");if(Profile.fleet.HasPending){if(Profile.fleet.pending!=null&&!string.IsNullOrEmpty(Profile.fleet.pending.id)&&Profile.fleet.pending.id==request&&Profile.fleet.pending.mode==mode&&Profile.fleet.pending.opponentKey==opponent)return Profile.fleet.pending;throw new InvalidOperationException("Race already committed");}if(Profile.spending.Exists(r=>r.transactionId==request))throw new InvalidOperationException("Race request was already completed");var option=Array.Find(RivalsData.Load().opponents,o=>o.id==opponent)??throw new InvalidOperationException("Unknown rival");var d=new DuelContract{id=request,mode=mode,playerId=Profile.fleet.selectedId,opponentId=Profile.profileId+":rival:"+request,opponentName=option.name,opponentKey=option.id,playerModelId=ActiveModelId,opponentModelId=string.IsNullOrEmpty(option.modelId)?"car_finch":option.modelId,playerBuild=FleetLedger.Clone(ActiveWorkshop),opponentBuild=FleetLedger.Clone(option.build),speedKph=option.speedKph,winCredits=option.winCredits,finishCredits=option.finishCredits,paint=Array.IndexOf(RivalsData.Load().opponents,option)};d.paint=opponent=="rookie"?0:opponent=="club"?1:2;FleetTransaction(Receipt(request,"duel_open",opponent,json:JsonUtility.ToJson(d)));return Profile.fleet.pending;}
 public void SettleDuel(DuelRaceSession race){if(race==null||!race.Resolved)throw new InvalidOperationException("A resolved physical race is required");FinishDuel(race.Contract,race.Result);}
 public void ForfeitDuel(){Refresh();if(CircuitLedger.Pending(Profile.fleet)){ForfeitCircuit();return;}if(Profile.fleet.pending!=null&&!string.IsNullOrEmpty(Profile.fleet.pending.id))FinishDuel(Profile.fleet.pending,"forfeit");}
 void FinishDuel(DuelContract d,string result){int reward=d.mode=="cash"?(result=="win"?d.winCredits:(result=="finish"||result=="draw")?d.finishCredits:0):0;var bytes=Guid.Parse(d.id).ToByteArray();bytes[15]^=0x80;FleetTransaction(Receipt(new Guid(bytes).ToString("N"),"duel_result",result,d.id,-reward));}
}
}
